package com.example.agendapersonal.ui;

import android.app.*;import android.os.Bundle;import android.widget.*;import android.view.View;
import com.example.agendapersonal.R;import com.example.agendapersonal.sync.*;
import org.json.*;import java.util.*;import java.util.function.Consumer;

public class ConexionActivity extends com.example.agendapersonal.ui.ActividadTematica {
 private MenuNavegacion menu;private CoordinadorSync sync;private EditText url,clave,correo,password;private TextView estado;private Switch automatico;private LinearLayout conflictos;private Consumer<String> observador;
 @Override protected void onCreate(Bundle b){super.onCreate(b);sync=CoordinadorSync.de(this);menu=new MenuNavegacion(this);setContentView(menu.getRaiz());menu.establecerContenido(R.layout.activity_conexion);findViewById(R.id.botonMenu).setOnClickListener(v->menu.alternar());url=findViewById(R.id.supabaseUrl);clave=findViewById(R.id.supabaseClave);correo=findViewById(R.id.supabaseCorreo);password=findViewById(R.id.supabasePassword);estado=findViewById(R.id.estadoConexion);automatico=findViewById(R.id.syncAutomatico);conflictos=findViewById(R.id.conflictosSync);automatico.setChecked(sync.automatico());automatico.setOnCheckedChangeListener((v,a)->sync.automatico(a));
  findViewById(R.id.iniciarSesion).setOnClickListener(v->iniciar());findViewById(R.id.sincronizarAhora).setOnClickListener(v->sync.solicitar(true,null));findViewById(R.id.desconectarSupabase).setOnClickListener(v->new AlertDialog.Builder(this).setMessage("Se cerrará la sesión en este dispositivo. Tus datos y cambios pendientes seguirán guardados localmente.").setNegativeButton("Volver",null).setPositiveButton("Desconectar",(d,w)->{sync.desconectar();automatico.setChecked(false);}).show());findViewById(R.id.actualizarConflictos).setOnClickListener(v->cargarConflictos());
  sync.ejecutar(()->{try{SesionSupabase s=new SesionSegura(this).leer();String proyecto;try(AlmacenSync a=new AlmacenSync(this)){proyecto=a.proyecto();}runOnUiThread(()->{if(isDestroyed())return;if(s!=null){url.setText(s.url);clave.setText(s.clave);correo.setText(s.email);}else if(proyecto!=null)url.setText(proyecto);});}catch(Exception e){runOnUiThread(()->estado.setText(CoordinadorSync.mensaje(e)));}});
  observador=texto->{estado.setText(texto);};
 }
 @Override protected void onStart(){super.onStart();sync.observar(observador);cargarConflictos();}
 @Override protected void onStop(){sync.dejarDeObservar(observador);super.onStop();}
 private void iniciar(){final String u,k,email,p;try{u=ReglasSync.urlProyecto(url.getText().toString());k=SupabaseRest.validarClave(clave.getText().toString());email=correo.getText().toString().trim();p=password.getText().toString();if(email.isEmpty()||p.isEmpty())throw new IllegalArgumentException("Completá el correo y la contraseña del usuario de la app");}catch(IllegalArgumentException e){estado.setText(e.getMessage());return;}findViewById(R.id.iniciarSesion).setEnabled(false);estado.setText("Iniciando sesión…");password.setText("");
  sync.ejecutar(()->{try{SesionSupabase s=SupabaseRest.iniciar(u,k,email,p);try(AlmacenSync a=new AlmacenSync(this)){a.comprobarCuenta(s.url,s.owner);}runOnUiThread(()->{if(isFinishing()||isDestroyed())return;findViewById(R.id.iniciarSesion).setEnabled(true);new AlertDialog.Builder(this).setTitle("Vincular esta agenda").setMessage("Cuenta: "+s.email+"\nProyecto: "+s.url+"\n\nSe vincularán los datos locales de este dispositivo a esa cuenta y se activará la sincronización automática. No se borran datos ni cambios pendientes.").setNegativeButton("Cancelar",null).setPositiveButton("Vincular y sincronizar",(d,w)->sync.activar(s,error->{if(isDestroyed())return;if(error!=null)estado.setText(error);else{automatico.setChecked(true);estado.setText(sync.estado());}})).show();});}catch(Exception e){runOnUiThread(()->{if(isDestroyed())return;findViewById(R.id.iniciarSesion).setEnabled(true);estado.setText(e instanceof SupabaseRest.ApiException&&(((SupabaseRest.ApiException)e).estado==400||((SupabaseRest.ApiException)e).estado==401)?"No se pudo iniciar sesión. Revisá el correo, la contraseña y que el usuario exista en Authentication > Users del proyecto.":CoordinadorSync.mensaje(e));});}});
 }
 private void cargarConflictos(){sync.ejecutar(()->{try{List<JSONObject> lista;try(AlmacenSync a=new AlmacenSync(this)){String owner=a.cuenta();lista=owner==null?Collections.emptyList():a.conflictos(owner);for(JSONObject c:lista){JSONObject actual=a.actualDelConflicto(owner,c.getString("change_id"));c.put("version_vista",actual==null?"null":actual.toString());}}runOnUiThread(()->{if(isDestroyed())return;conflictos.removeAllViews();if(lista.isEmpty()){TextView t=new TextView(this);t.setText("No hay conflictos pendientes");conflictos.addView(t);}for(JSONObject c:lista){Button b=new Button(this);b.setAllCaps(false);b.setText(c.optString("entity_type")+" · "+c.optString("entity_id"));b.setOnClickListener(v->verConflicto(c));conflictos.addView(b);}});}catch(Exception e){runOnUiThread(()->estado.setText(CoordinadorSync.mensaje(e)));}});}
 private String describir(JSONObject p){if(p==null)return "No hay versión local";StringBuilder t=new StringBuilder();Iterator<String>k=p.keys();while(k.hasNext()){String clave=k.next();if(clave.equals(AlmacenSync.RESOLUCION))continue;t.append(clave).append(": ").append(p.opt(clave)).append('\n');}return t.toString();}
 private void verConflicto(JSONObject c){try{String version=c.getString("version_vista");JSONObject local=version.equals("null")?null:new JSONObject(version);JSONObject remoto=new JSONObject(c.getString("remote_change")).getJSONObject("payload");TextView texto=new TextView(this);texto.setText("VERSIÓN LOCAL ACTUAL\n\n"+describir(local)+"\nVERSIÓN RECIBIDA\n\n"+describir(remoto)+"\nSi la versión local cambia después de abrir esta pantalla, se pedirá revisar nuevamente antes de resolver.");texto.setTextIsSelectable(true);texto.setPadding(24,16,24,16);ScrollView scroll=new ScrollView(this);scroll.addView(texto);AlertDialog.Builder dialogo=new AlertDialog.Builder(this).setTitle("Resolver sin perder el historial").setView(scroll).setNegativeButton("Revisar después",null).setPositiveButton("Usar recibido",(d,w)->confirmar(c,true));if(local!=null)dialogo.setNeutralButton("Conservar local",(d,w)->confirmar(c,false));dialogo.show();}catch(JSONException e){estado.setText("No se pudo leer el conflicto");}}
 private void confirmar(JSONObject c,boolean remoto){new AlertDialog.Builder(this).setMessage(remoto?"¿Usar la versión recibida? La versión local se conserva en el historial y se generará un cambio nuevo.":"¿Conservar la versión local actual? La versión recibida se conserva en el historial y se generará un cambio nuevo.").setNegativeButton("Volver",null).setPositiveButton("Resolver",(d,w)->sync.ejecutar(()->{try(AlmacenSync a=new AlmacenSync(this)){String owner=a.cuenta();String device=getSharedPreferences("agenda_identidad",MODE_PRIVATE).getString("device_id","");a.resolver(owner,device,c.getString("change_id"),remoto,c.getString("version_vista"));runOnUiThread(()->{estado.setText("Conflicto resuelto; el cambio nuevo quedó pendiente de envío");cargarConflictos();});sync.solicitar(false,null);}catch(Exception e){runOnUiThread(()->estado.setText(CoordinadorSync.mensaje(e)));}})).show();}
 @Override public void onBackPressed(){if(menu.estaAbierto())menu.cerrar();else super.onBackPressed();}
}
